import{c as s,ah as a,L as e,O as l}from"./chunks/framework.YKVbmyBD.js";const k=JSON.parse('{"title":"安装与管理软件","description":"","frontmatter":{},"headers":[],"relativePath":"web-src/fovlin-notes/linux-guide/configure-system/application-install-manage.md","filePath":"web-src/fovlin-notes/linux-guide/configure-system/application-install-manage.md"}'),t={name:"web-src/fovlin-notes/linux-guide/configure-system/application-install-manage.md"};function n(d,i,h,p,o,c){return a(),e("div",null,[...i[0]||(i[0]=[l(`<h1 id="安装与管理软件" tabindex="-1">安装与管理软件 <a class="header-anchor" href="#安装与管理软件" aria-label="Permalink to “安装与管理软件”">​</a></h1><p>通常来说，软件包的安装都是借助系统的包管理工具，除此之外，在应用官网寻找安装包也是不错的选择。</p><p>一些官方还会提供可自行编译安装的源代码，以及与系统隔离的可运行文件。</p><h2 id="包管理器安装" tabindex="-1">包管理器安装 <a class="header-anchor" href="#包管理器安装" aria-label="Permalink to “包管理器安装”">​</a></h2><p>包管理器是发行版自带的管理软件包的工具，例如 Ubuntu 和 <code>Dibian</code> 使用 <code>apt</code> 和 <code>dpkg</code> 包管理器，Fedora 使用 <code>dnf</code> 以及 <code>rpm</code> 包管理器。</p><p>要了解包管理器的用法，建议参阅对应发行版的官网文档。</p><p>同时也存在第三方的软件包管理器，如 <code>flatpak</code>。</p><h2 id="安装软件包" tabindex="-1">安装软件包 <a class="header-anchor" href="#安装软件包" aria-label="Permalink to “安装软件包”">​</a></h2><p>某些软件包无法通过包管理器安装，此时需要手动安装。</p><p>前往软件包官网下载安装包，这可能为 <code>.deb</code>、<code>.rpm</code>、<code>.tar.gz</code> 等格式，其中<code>.deb</code> 格式为 Debian/Ubuntu 系统，<code>.rpm</code> 格式为 Fedora 系统，<code>.tar.gz</code> 格式解压后通常为源码或独立运行程序。</p><h3 id="对于-deb-rpm-格式安装包" tabindex="-1">对于 <code>.deb</code> <code>.rpm</code> 格式安装包 <a class="header-anchor" href="#对于-deb-rpm-格式安装包" aria-label="Permalink to “对于 .deb .rpm 格式安装包”">​</a></h3><ul><li><code>.deb</code> 格式在 Debian/Ubuntu 系统中安装，使用 <code>dpkg -i</code> 命令。</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package.deb</span></span></code></pre></div><ul><li><code>.rpm</code> 格式在 Fedora 系统中安装，使用 <code>rpm -ivh</code> 命令。</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ivh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package.rpm</span></span></code></pre></div><h3 id="对于-tar-gz-文件" tabindex="-1">对于 tar.gz 文件 <a class="header-anchor" href="#对于-tar-gz-文件" aria-label="Permalink to “对于 tar.gz 文件”">​</a></h3><h4 id="通过源码编译安装" tabindex="-1">通过源码编译安装 <a class="header-anchor" href="#通过源码编译安装" aria-label="Permalink to “通过源码编译安装”">​</a></h4><p>此类文件可分为源码、预编译的二进制包、独立的可运行程序几类，这些程序通常跨发行版可用。</p><p>源码可通过编译安装，请在编译前安装编译工具链。</p><p>随后解压 <code>tar.gz</code> 文件，进入目录，源码应当存在 <code>configure</code> 文件，此文件用于配置编译参数，运行此文件并在后附加编译参数，参数因软件而异。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./configure</span></span></code></pre></div><p>随后编译并安装</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h4 id="通过预编译二进制文件安装" tabindex="-1">通过预编译二进制文件安装 <a class="header-anchor" href="#通过预编译二进制文件安装" aria-label="Permalink to “通过预编译二进制文件安装”">​</a></h4><p>此类文件解压后通常会有 <code>bin</code> 目录存放应用程序文件，一般来说直接运行此文件夹内的可运行程序即可。</p><h4 id="独立应用程序" tabindex="-1">独立应用程序 <a class="header-anchor" href="#独立应用程序" aria-label="Permalink to “独立应用程序”">​</a></h4><p>为打包好的应用程序，通常为 <code>AppImage</code> 格式，直接运行此文件即可使用。</p><h3 id="使应用程序全局可用" tabindex="-1">使应用程序全局可用 <a class="header-anchor" href="#使应用程序全局可用" aria-label="Permalink to “使应用程序全局可用”">​</a></h3><p>当我们在控制台输入命令时，系统会扫描包含在 <code>PATH</code> 变量目录下的文件，使用 <code>echo $PATH</code> 即可查看所有包含在此变量下的目录。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $PATH</span></span></code></pre></div><p>例如出现以下输出：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fovlin@archlinux:~$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $PATH</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/usr/local/bin:/usr/bin:/bin:/usr/local/sbin</span></span></code></pre></div><p>表示运行命令时会扫描 <code>/usr/local/bin</code> 、 <code>/usr/bin</code> 、 <code>/bin</code> 、 <code>/usr/local/sbin</code> 这几个路径下的文件，寻找可运行程序，即在安装应用程序时可以将可运行程序所在的文件夹添加到 <code>$PATH</code> 中，或创建软链接到任意一个在 <code>$PATH</code> 路径下的文件夹，如将 <code>/home/fovlin/opt/vscode/bin/code</code> 全局可用。</p><p>既可以添加 <code>/home/fovlin/opt/vscode/bin/</code> 到 <code>PATH</code>：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATH=/home/fovlin/opt/vscode/bin/:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/profile</span></span></code></pre></div><blockquote><p>也可以将将 <code>/etc/profile</code> 改为 <code>~/.profile</code> 以此仅对用户生效。</p></blockquote><p>也可以将 <code>/home/fovlin/opt/vscode/bin/code</code> 创建软链接到 <code>$PATH</code> 目录下：</p><p>创建到 <code>/usr/local/bin</code> 为例（推荐）</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/fovlin/opt/vscode/bin/code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/code</span></span></code></pre></div><p>如需添加应用到 Applications list，需要创建 <code>.desktop</code> 文件，并保存在 <code>/usr/share/applications</code> 或 <code>~/.local/share/applications</code> 目录下，前者为系统级应用，后者为用户级应用。</p><p>例如创建 <code>idea.desktop</code> 文件，并保存在 <code>/usr/share/applications</code> 目录下：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Desktop Entry]</span></span>
<span class="line"><span>Type=Application</span></span>
<span class="line"><span>Exec=/opt/idea/bin/idea.sh</span></span>
<span class="line"><span>Icon=/opt/idea/bin/idea.png</span></span>
<span class="line"><span>Name=IDEA</span></span></code></pre></div><ul><li><p>Exec 为可执行文件的绝对路径，其后的参数本质为运行该应用时执行的命令。</p></li><li><p>Icon 为图标文件的绝对路径。</p></li><li><p>Name 为应用名称。</p></li></ul><p>添加完成后，在应用程序栏中就可以看到该应用了。</p>`,44)])])}const g=s(t,[["render",n]]);export{k as __pageData,g as default};
